export class HttpProjectGateway implements ProjectGateway {
  private readonly baseUrl: string

  constructor(baseUrl: string) {
    this.baseUrl = baseUrl
  }

  async list(signal?: AbortSignal): Promise<ProjectRecord[]> {
    const response = await fetch(`${this.baseUrl}/api/projects`, { signal })
    if (!response.ok) throw new Error(`GET /api/projects answered ${response.status}`)
    return (await response.json()) as ProjectRecord[]
  }
}
