import { useEffect, useState } from 'react'

import type { ProjectViewModel } from '../../application/ProjectViewModel'
import { useProjectsUseCases } from '../useProjectsUseCases/useProjectsUseCases'

export type ProjectsState =
  | { readonly status: 'loading' }
  | { readonly status: 'loaded'; readonly projects: ProjectViewModel[] }
  | { readonly status: 'failed' }

export const useProjects = (): ProjectsState => {
  const { listProjects } = useProjectsUseCases()
  const [state, setState] = useState<ProjectsState>({ status: 'loading' })

  useEffect(() => {
    const controller = new AbortController()
    listProjects.execute(controller.signal).then(
      (projects) => setState({ status: 'loaded', projects }),
      () => {
        if (!controller.signal.aborted) setState({ status: 'failed' })
      },
    )
    return () => controller.abort()
  }, [listProjects])

  return state
}
